(function(){
  const q=s=>document.querySelector(s);let imageUrl=null,worker=null;
  const statusText={loading_tesseract_core:'OCR 엔진 로드 중',initializing_tesseract:'OCR 엔진 준비 중',loading_language_traineddata:'한국어·영어 모델 로드 중',initializing_api:'인식 모델 초기화 중',recognizing_text:'성적표 글자 인식 중'};
  function update(m){q('#ocrStatus').textContent=statusText[String(m.status).replaceAll(' ','_')]||m.status||'처리 중';if(Number.isFinite(m.progress))q('#ocrProgress').value=m.progress}
  function reset(){if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=null;q('#transcriptImage').value='';q('#ocrPreview').removeAttribute('src');q('#ocrWorkspace').classList.add('hidden');q('#ocrReview').classList.add('hidden');q('#ocrProgress').value=0;q('#ocrStatus').textContent='사진 준비 완료'}
  async function dispose(){reset();q('#ocrRawText').value='';q('#ocrReviewBody').innerHTML='';q('#ocrHint').textContent='사진은 브라우저 안에서만 처리되며 서버로 전송하지 않습니다.';if(worker){await worker.terminate();worker=null}}
  function editable(key,value,type='text'){const safe=String(value??'').replace(/"/g,'&quot;');return `<input data-field="${key}" type="${type}" value="${safe}">`}
  function renderRows(rows){q('#ocrReviewBody').innerHTML=rows.map((r,i)=>`<tr data-ocr-row="${i}"><td><input data-field="selected" type="checkbox" ${r.confidence>=70?'checked':''}></td><td>${editable('grade',r.grade,'number')}</td><td>${editable('semester',r.semester,'number')}</td><td>${editable('subject',r.subject)}</td><td>${editable('name',r.name)}</td><td>${editable('credits',r.credits??'','number')}</td><td>${editable('rankGrade',r.rankGrade??'','number')}</td><td>${editable('achievement',r.achievement)}</td><td class="confidence-${r.confidence>=80?'high':r.confidence>=60?'mid':'low'}">${r.confidence}%</td></tr>`).join('');q('#ocrReview').classList.remove('hidden');q('#ocrHint').textContent=rows.length?`${rows.length}개 후보를 찾았습니다. 등급·학점·성취도를 원본과 반드시 대조하세요.`:'과목 행을 찾지 못했습니다. OCR 원문을 수정하거나 더 가깝게 다시 찍어 주세요.'}
  async function run(){if(!imageUrl)return;const btn=q('#runOcr');btn.disabled=true;q('#ocrReview').classList.add('hidden');try{if(location.protocol==='file:')throw new Error('OCR은 브라우저 보안 제한으로 파일을 직접 열었을 때 실행할 수 없습니다. start-preview.ps1로 로컬 서버를 실행하거나 배포된 사이트에서 이용하세요.');if(!window.Tesseract)throw new Error('OCR 라이브러리를 불러오지 못했습니다.');worker=worker||await Tesseract.createWorker('kor+eng',Tesseract.OEM.LSTM_ONLY,{workerPath:'vendor/worker.min.js',langPath:'vendor/lang',corePath:'vendor/tesseract-core-simd-lstm.wasm.js',logger:update});const result=await worker.recognize(imageUrl);q('#ocrRawText').value=result.data.text||'';renderRows(TranscriptParser.parse(result.data.text));q('#ocrStatus').textContent=`인식 완료 · 전체 신뢰도 ${Math.round(result.data.confidence||0)}%`;q('#ocrProgress').value=1}catch(err){q('#ocrStatus').textContent='인식에 실패했습니다.';q('#ocrHint').textContent=err.message||String(err)}finally{btn.disabled=false}}
  q('#transcriptImage').addEventListener('change',e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){alert('이미지 파일만 선택할 수 있습니다.');return}if(imageUrl)URL.revokeObjectURL(imageUrl);imageUrl=URL.createObjectURL(file);q('#ocrPreview').src=imageUrl;q('#ocrWorkspace').classList.remove('hidden');q('#ocrReview').classList.add('hidden');q('#ocrStatus').textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)}MB`;q('#ocrProgress').value=0});
  q('#removeImage').addEventListener('click',reset);q('#runOcr').addEventListener('click',run);q('#reparseOcr').addEventListener('click',()=>renderRows(TranscriptParser.parse(q('#ocrRawText').value)));
  q('#applyOcr').addEventListener('click',()=>{let count=0;document.querySelectorAll('[data-ocr-row]').forEach(tr=>{const read=k=>tr.querySelector(`[data-field="${k}"]`);if(!read('selected').checked)return;const data={};['grade','semester','subject','name','credits','rankGrade','achievement'].forEach(k=>data[k]=['grade','semester','credits','rankGrade'].includes(k)?(read(k).value===''?null:Number(read(k).value)):read(k).value);data.type=data.achievement?'진로선택':'공통과목';window.addRow(data);count++});q('#ocrHint').textContent=`확인한 ${count}개 과목을 상세 입력에 추가했습니다.`;window.saveMaybe?.()});
  window.clearTranscriptPhoto=dispose;
  window.addEventListener('pagehide',()=>{worker?.terminate();if(imageUrl)URL.revokeObjectURL(imageUrl)})
})();
